"use client";

// Googly Eyes Cursor — Goodmotion
// Website: https://goodmotion.vercel.app/
// Dependencies: npm i gsap @gsap/react

import React, { useEffect, useRef, useState, type CSSProperties } from "react"
import { createPortal } from "react-dom"
import { gsap } from "gsap"
import { useGSAP } from "@gsap/react"

// Register GSAP plugins safely for SSR/Client
if (typeof window !== "undefined") {
    gsap.registerPlugin(useGSAP)
}

export interface GooglyEyesCursorProps {
    /** Accent color for borders, pupils, and hover badge (default: "#E53935") */
    accentColor?: string
    /** Whether to hide the native OS mouse cursor (default: true) */
    hideDefaultCursor?: boolean
    /** Alias for hideDefaultCursor */
    hideNativeCursor?: boolean
    /** Custom z-index for the cursor container (default: 2147483647) */
    zIndex?: number
    /** Optional custom CSS class name */
    className?: string
    /** Optional inline styles */
    style?: CSSProperties
    /** Optional child elements wrapped within the component */
    children?: React.ReactNode
}

export function Component({
    accentColor = "#0068FF",
    hideDefaultCursor = true,
    hideNativeCursor,
    zIndex = 2147483647,
    className,
    style,
    children,
}: GooglyEyesCursorProps) {
    const shouldHideCursor = hideNativeCursor ?? hideDefaultCursor

    const eyeWidth = 26
    const eyeHeight = 36
    const eyeSpacing = 4
    const borderWidth = 2
    const backgroundColor = "#FFFFFF"
    const followSpeed = 0.05
    const gazeIntensity = 1.0

    const containerRef = useRef<HTMLDivElement>(null)
    const eyeLeftRef = useRef<HTMLDivElement>(null)
    const eyeRightRef = useRef<HTMLDivElement>(null)
    const pupilLeftRef = useRef<HTMLDivElement>(null)
    const pupilRightRef = useRef<HTMLDivElement>(null)
    const badgeRef = useRef<HTMLDivElement>(null)

    const prevMousePos = useRef({ x: 0, y: 0 })
    const isBlinkingRef = useRef(false)
    const currentAngleRef = useRef<number>(Math.PI / 2)

    const [mounted, setMounted] = useState(false)
    const [isPointerDevice, setIsPointerDevice] = useState(false)

    // Inspect client environment and hardware pointer capabilities
    useEffect(() => {
        const hasFinePointer = window.matchMedia("(pointer: fine)").matches
        const prefersReducedMotion = window.matchMedia(
            "(prefers-reduced-motion: reduce)"
        ).matches

        if (hasFinePointer && !prefersReducedMotion) {
            setIsPointerDevice(true)
        }
        setMounted(true)
    }, [])

    useGSAP(
        () => {
            if (!mounted || !isPointerDevice) return

            const cursor = containerRef.current
            const eyeLeft = eyeLeftRef.current
            const eyeRight = eyeRightRef.current
            const pupilLeft = pupilLeftRef.current
            const pupilRight = pupilRightRef.current
            const badge = badgeRef.current

            if (!cursor || !eyeLeft || !eyeRight || !pupilLeft || !pupilRight || !badge) return

            // 1. Manage native cursor visibility with reference counting to prevent cursor loss
            const styleId = "gm-googly-cursor-override"
            let isStyleInjected = false

            if (shouldHideCursor) {
                const currentCount = Number(
                    document.body.getAttribute("data-gm-googly-cursor-count") || "0"
                )
                document.body.setAttribute(
                    "data-gm-googly-cursor-count",
                    String(currentCount + 1)
                )
                isStyleInjected = true

                let styleTag = document.getElementById(styleId) as HTMLStyleElement | null
                if (!styleTag) {
                    styleTag = document.createElement("style")
                    styleTag.id = styleId
                    styleTag.innerHTML = `
                        html, body, *, *::before, *::after {
                            cursor: none !important;
                        }
                        input, textarea, select, [contenteditable], [contenteditable] * {
                            cursor: text !important;
                        }
                        select, option {
                            cursor: pointer !important;
                        }
                    `
                    document.head.appendChild(styleTag)
                }
            }

            // 2. Initial state configuration
            const pupilSize = eyeWidth * 0.44
            const maxRadiusX = (eyeWidth / 2 - pupilSize / 2 - borderWidth) * gazeIntensity
            const maxRadiusY = (eyeHeight / 2 - pupilSize / 2 - borderWidth) * gazeIntensity

            const initX = Math.cos(currentAngleRef.current) * maxRadiusX
            const initY = Math.sin(currentAngleRef.current) * maxRadiusY

            gsap.set(cursor, { xPercent: -50, yPercent: -50, opacity: 0 })
            gsap.set(badge, { opacity: 0, scale: 0.8, x: 10 })
            gsap.set([pupilLeft, pupilRight], { x: initX, y: initY })

            const xTo = gsap.quickTo(cursor, "x", { duration: followSpeed, ease: "power2.out" })
            const yTo = gsap.quickTo(cursor, "y", { duration: followSpeed, ease: "power2.out" })

            // 3. Eye blinking logic
            const triggerBlink = () => {
                if (isBlinkingRef.current) return
                isBlinkingRef.current = true

                gsap.timeline({
                    onComplete: () => {
                        isBlinkingRef.current = false
                    },
                })
                    .to([eyeLeft, eyeRight], {
                        scaleY: 0.05,
                        duration: 0.14,
                        ease: "power2.inOut",
                        transformOrigin: "center center",
                    })
                    .to([eyeLeft, eyeRight], {
                        scaleY: 1,
                        duration: 0.2,
                        ease: "power2.out",
                    })
            }

            const blinkInterval = setInterval(triggerBlink, 2600)
            const handleMouseDown = () => triggerBlink()

            let hasMoved = false

            const updatePupilAngle = (targetAngle: number, duration: number = 0.28) => {
                currentAngleRef.current = targetAngle
                const targetX = Math.cos(targetAngle) * maxRadiusX
                const targetY = Math.sin(targetAngle) * maxRadiusY

                gsap.to([pupilLeft, pupilRight], {
                    x: targetX,
                    y: targetY,
                    duration: duration,
                    ease: "power2.out",
                    overwrite: "auto",
                })
            }

            // 4. Pointer interactions
            const handlePointerMove = (e: PointerEvent) => {
                // Strict touch hygiene: Never track touch events on mobile/tablets
                if (e.pointerType === "touch") return

                const mouseX = e.clientX
                const mouseY = e.clientY

                if (!hasMoved) {
                    gsap.set(cursor, { x: mouseX, y: mouseY, opacity: 1 })
                    hasMoved = true
                    prevMousePos.current = { x: mouseX, y: mouseY }
                    return
                } else {
                    xTo(mouseX)
                    yTo(mouseY)
                }

                const deltaX = mouseX - prevMousePos.current.x
                const deltaY = mouseY - prevMousePos.current.y
                const dist = Math.hypot(deltaX, deltaY)

                if (dist > 2) {
                    prevMousePos.current = { x: mouseX, y: mouseY }
                    const angle = Math.atan2(deltaY, deltaX)
                    updatePupilAngle(angle, 0.25)
                }

                const targetEl = e.target as HTMLElement | null
                const isClickable = targetEl?.closest(
                    "a, button, [role='button'], input, textarea, select"
                )

                if (isClickable) {
                    gsap.to(badge, {
                        opacity: 1,
                        scale: 1,
                        x: 14,
                        duration: 0.2,
                        ease: "power2.out",
                        overwrite: "auto",
                    })
                } else {
                    gsap.to(badge, {
                        opacity: 0,
                        scale: 0.8,
                        x: 10,
                        duration: 0.2,
                        ease: "power2.out",
                        overwrite: "auto",
                    })
                }
            }

            let lastScroll = typeof window !== "undefined" ? window.scrollY : 0
            const handleScroll = () => {
                const currentScroll = window.scrollY
                const delta = currentScroll - lastScroll
                lastScroll = currentScroll

                if (Math.abs(delta) > 1) {
                    const isLeftSide = Math.cos(currentAngleRef.current) < 0
                    if (delta > 0) {
                        updatePupilAngle(Math.PI / 2, 0.35)
                    } else {
                        const topAngle = isLeftSide ? -Math.PI * 0.75 : -Math.PI * 0.25
                        updatePupilAngle(topAngle, 0.35)
                    }
                }
            }

            const handleMouseLeave = () => {
                gsap.to(cursor, { opacity: 0, duration: 0.2 })
                hasMoved = false
            }

            const handleMouseEnter = () => {
                if (hasMoved) {
                    gsap.to(cursor, { opacity: 1, duration: 0.2 })
                }
            }

            window.addEventListener("pointermove", handlePointerMove, { passive: true })
            window.addEventListener("mousedown", handleMouseDown)
            window.addEventListener("scroll", handleScroll, { passive: true })
            document.addEventListener("mouseleave", handleMouseLeave)
            document.addEventListener("mouseenter", handleMouseEnter)

            // 5. Teardown and cleanup on unmount
            return () => {
                clearInterval(blinkInterval)
                window.removeEventListener("pointermove", handlePointerMove)
                window.removeEventListener("mousedown", handleMouseDown)
                window.removeEventListener("scroll", handleScroll)
                document.removeEventListener("mouseleave", handleMouseLeave)
                document.removeEventListener("mouseenter", handleMouseEnter)

                if (isStyleInjected) {
                    const remainingCount = Number(
                        document.body.getAttribute("data-gm-googly-cursor-count") || "1"
                    ) - 1
                    if (remainingCount <= 0) {
                        document.body.removeAttribute("data-gm-googly-cursor-count")
                        const elToRemove = document.getElementById(styleId)
                        if (elToRemove && elToRemove.parentNode) {
                            elToRemove.parentNode.removeChild(elToRemove)
                        }
                    } else {
                        document.body.setAttribute(
                            "data-gm-googly-cursor-count",
                            String(remainingCount)
                        )
                    }
                }
            }
        },
        {
            scope: containerRef,
            dependencies: [mounted, isPointerDevice, accentColor, shouldHideCursor],
        }
    )

    const pupilSize = eyeWidth * 0.44
    const highlightSize = pupilSize * 0.32

    return (
        <>
            {children}
            {mounted && isPointerDevice && typeof document !== "undefined" && createPortal(
                <div
                    ref={containerRef}
                    className={className}
                    style={{
                        position: "fixed",
                        top: 0,
                        left: 0,
                        zIndex,
                        pointerEvents: "none",
                        display: "flex",
                        alignItems: "center",
                        userSelect: "none",
                        willChange: "transform",
                        ...style,
                    }}
                >
                    <div style={{ display: "flex", alignItems: "center", gap: `${eyeSpacing}px` }}>
                        {/* Left eye */}
                        <div
                            ref={eyeLeftRef}
                            style={{
                                width: `${eyeWidth}px`,
                                height: `${eyeHeight}px`,
                                borderRadius: "50% / 50%",
                                backgroundColor: backgroundColor,
                                border: `${borderWidth}px solid ${accentColor}`,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                position: "relative",
                                overflow: "hidden",
                            }}
                        >
                            <div
                                ref={pupilLeftRef}
                                style={{
                                    width: `${pupilSize}px`,
                                    height: `${pupilSize}px`,
                                    borderRadius: "50%",
                                    backgroundColor: accentColor,
                                    position: "absolute",
                                    display: "flex",
                                    alignItems: "flex-start",
                                    justifyContent: "flex-end",
                                    padding: "2px",
                                }}
                            >
                                <div
                                    style={{
                                        width: `${highlightSize}px`,
                                        height: `${highlightSize}px`,
                                        borderRadius: "50%",
                                        backgroundColor: "#FFFFFF",
                                    }}
                                />
                            </div>
                        </div>

                        {/* Right eye */}
                        <div
                            ref={eyeRightRef}
                            style={{
                                width: `${eyeWidth}px`,
                                height: `${eyeHeight}px`,
                                borderRadius: "50% / 50%",
                                backgroundColor: backgroundColor,
                                border: `${borderWidth}px solid ${accentColor}`,
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                position: "relative",
                                overflow: "hidden",
                            }}
                        >
                            <div
                                ref={pupilRightRef}
                                style={{
                                    width: `${pupilSize}px`,
                                    height: `${pupilSize}px`,
                                    borderRadius: "50%",
                                    backgroundColor: accentColor,
                                    position: "absolute",
                                    display: "flex",
                                    alignItems: "flex-start",
                                    justifyContent: "flex-end",
                                    padding: "2px",
                                }}
                            >
                                <div
                                    style={{
                                        width: `${highlightSize}px`,
                                        height: `${highlightSize}px`,
                                        borderRadius: "50%",
                                        backgroundColor: "#FFFFFF",
                                    }}
                                />
                            </div>
                        </div>
                    </div>

                    {/* Click badge */}
                    <div
                        ref={badgeRef}
                        style={{
                            backgroundColor: accentColor,
                            border: `1.5px solid ${accentColor}`,
                            borderRadius: "9999px",
                            padding: "5px 8px",
                            fontSize: "14px",
                            fontWeight: 600,
                            lineHeight: 1,
                            color: "#FFFFFF",
                            letterSpacing: "0.02em",
                            whiteSpace: "nowrap",
                            pointerEvents: "none",
                            fontFamily:
                                "system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
                        }}
                    >
                        click
                    </div>
                </div>,
                document.body
            )}
        </>
    )
}

export default Component;

